const prMeta = $('Extract PR Metadata').first().json;
const files = $input.all();

// Build file summary (patch limited to avoid token overflow)
const fileSummaries = files.map(f => {
  const file = f.json;
  const patch = (file.patch || '').substring(0, 500);
  const patchPreview = patch ? `\n  Diff preview:\n  ${patch.split('\n').slice(0, 15).join('\n  ')}` : '';
  return `- ${file.filename} (+${file.additions}/-${file.deletions} lines, status: ${file.status})${patchPreview}`;
}).join('\n');

const changedFiles = files.map(f => f.json.filename).join(', ');
const totalAdditions = files.reduce((s, f) => s + (f.json.additions || 0), 0);
const totalDeletions = files.reduce((s, f) => s + (f.json.deletions || 0), 0);

return [{
  json: {
    pr_number: prMeta.pr_number,
    pr_title: prMeta.pr_title,
    pr_body: prMeta.pr_body,
    pr_author: prMeta.pr_author,
    pr_base_branch: prMeta.pr_base_branch,
    pr_head_branch: prMeta.pr_head_branch,
    repo_full_name: prMeta.repo_full_name,
    pr_url: prMeta.pr_url,
    changed_files: changedFiles,
    total_files: files.length,
    total_additions: totalAdditions,
    total_deletions: totalDeletions,
    file_summaries: fileSummaries
  }
}];

