const llmResponse = $input.first().json;
const docText = llmResponse?.content?.[0]?.text || llmResponse?.choices?.[0]?.message?.content || 'Error generating documentation';
const ctx = $('Build Context').first().json;

const comment = `## 🤖 Auto-generated PR Documentation\n\n> Generated by [ClickIT PR Docs Bot](https://github.com/ClickITMx/clickit-agentic-low-code-templates) | n8n workflow\n\n${docText}\n\n---\n*This documentation was generated automatically. Please review and update as needed.*`;

return [{
  json: {
    repo: ctx.repo_full_name,
    pr_number: ctx.pr_number,
    comment_body: comment
  }
}];
